function openBatch(mode='produce'){
 const preparing=mode==='produce',selected=new Map(),genders=['Dama','Caballero','Unisex'];
 $('#modal-title').textContent=preparing?'Iniciar producción':'Registrar stock existente';$('#modal').classList.add('batch-modal');
 $('#form > .primary').textContent=preparing?'Preparar perfumes seleccionados':'Ingresar perfumes seleccionados';
 const recipe50=recipeFor(50),recipe100=recipeFor(100);
 $('#fields').innerHTML=`${preparing?productionPurposeFields():''}<p>Busca por nombre o referencia de inspiración, selecciona los perfumes y revisa las cantidades en la tabla inferior.</p>${[100,50].map(size=>`<details class="batch-section" data-size="${size}" ${size===100?'open':''}><summary>Perfumes de ${size} ml <span id="count-${size}">0 seleccionados</span></summary><div class="batch-inner"><label class="field">Buscar perfume<input type="search" data-batch-search="${size}" placeholder="Ej. Sauvage, Acqua di Giò, Ambroxan Sky…"></label><div class="batch-list" id="list-${size}"></div></div></details>`).join('')}${preparing?`<div class="notice"><strong>Fórmula fija por envase</strong><br>50 ml: ${recipe50.essence} ml de esencia + ${recipe50.fixative} ml de galaxolide + ${recipe50.alcohol} ml de alcohol.<br>100 ml: ${recipe100.essence} ml de esencia + ${recipe100.fixative} ml de galaxolide + ${recipe100.alcohol} ml de alcohol.</div>`:'<div class="notice">Solo se agregarán perfumes ya preparados; no se descontarán materias primas.</div>'}<section class="selection-section" aria-labelledby="selection-title"><h3 id="selection-title">Perfumes seleccionados</h3><p>Puedes cambiar el número de envases o eliminar perfumes desde esta tabla.</p><div id="selected-perfumes"></div></section><p id="batch-total" aria-live="polite"></p>`;
 const fields=$('#fields');
 function renderSelections(){
  const items=[...selected.entries()];$('#selected-perfumes').innerHTML=items.length?`<div class="table-wrap selection-table"><table><thead><tr><th>Perfume</th><th>Tamaño</th><th>Envases</th><th></th></tr></thead><tbody>${genders.map(gender=>{const rows=items.filter(([,item])=>product(item.id).category===gender);return rows.length?`<tr class="group-heading"><th colspan="4">${gender}</th></tr>`+rows.map(([key,item])=>{const p=product(item.id);return `<tr data-selected-row="${key}"><td>${esc(p.name)}<small>Inspirado en ${esc(p.displayReference??p.reference)} · ${p.line}</small></td><td>${item.size} ml</td><td><input type="number" min="1" step="1" required value="${item.qty}" data-selected-qty="${key}" aria-label="Envases seleccionados de ${esc(p.name)} de ${item.size} ml"></td><td><button type="button" class="text-button remove-selection" data-selection-remove="${key}" aria-label="Eliminar ${esc(p.name)} de ${item.size} ml">Eliminar</button></td></tr>`}).join(''):'';}).join('')}</tbody></table></div>`:'<div class="empty">Todavía no has seleccionado perfumes.</div>';
 }
 function update(redraw=true){
  for(const size of [100,50])$('#count-'+size).textContent=[...selected.values()].filter(x=>x.size===size).length+' seleccionados';
  const items=[...selected.values()],frascos=items.reduce((n,x)=>n+x.qty,0),ml=items.reduce((n,x)=>n+x.qty*x.size,0),alcohol=items.reduce((n,x)=>n+x.qty*recipeFor(x.size).alcohol,0),essence=items.reduce((n,x)=>n+x.qty*recipeFor(x.size).essence,0),fixative=items.reduce((n,x)=>n+x.qty*recipeFor(x.size).fixative,0);
  $('#batch-total').textContent=`${items.length} presentaciones seleccionadas · ${num(frascos)} envases · ${num(ml)} ml en total.${preparing?` Consumo: ${num(essence)} ml de esencia · ${num(fixative)} ml de galaxolide · ${num(alcohol)} ml de alcohol.`:''}`;
  if(redraw)renderSelections();
 }
 function list(size,query=''){
  const items=catalog.filter(p=>matches(p,query)).sort((a,b)=>perfumeGroups.indexOf(perfumeGroup(a))-perfumeGroups.indexOf(perfumeGroup(b)));let previousGroup='';
  $('#list-'+size).innerHTML=items.map(p=>{const k=p.id+'-'+size,item=selected.get(k),group=perfumeGroup(p),heading=group!==previousGroup?`<div class="batch-group">${group}</div>`:'';previousGroup=group;return `${heading}<div class="batch-row"><label class="batch-choice"><input type="checkbox" data-batch-check="${k}" ${item?'checked':''}><span><strong>${esc(p.name)}</strong><small>Inspirado en ${esc(p.displayReference??p.reference)}</small></span></label><label class="batch-quantity">Envases<input type="number" min="1" step="1" value="${item?.qty??1}" data-batch-qty="${k}" aria-label="Frascos de ${esc(p.name)} de ${size} ml" ${item?'required':'disabled'}></label></div>`}).join('')||'<div class="empty">No se encontraron perfumes.</div>';
 }
 for(const size of [100,50])list(size);
 fields.oninput=e=>{
  if(e.target.dataset.batchSearch)list(+e.target.dataset.batchSearch,e.target.value);
  const key=e.target.dataset.batchQty||e.target.dataset.selectedQty;if(!key||!selected.has(key))return;
  selected.get(key).qty=Number(e.target.value);const counterpart=fields.querySelector(e.target.dataset.selectedQty?`[data-batch-qty="${key}"]`:`[data-selected-qty="${key}"]`);if(counterpart)counterpart.value=e.target.value;
  update(false);
 };
 fields.onchange=e=>{
  if(e.target.name==='productionType'){syncProductionPurpose();return;}const key=e.target.dataset.batchCheck;if(!key)return;const[id,size]=key.split('-'),qty=fields.querySelector(`[data-batch-qty="${key}"]`);
  if(e.target.checked){selected.set(key,{id,size:+size,qty:Number(qty.value)});qty.disabled=false;qty.required=true;}else{selected.delete(key);qty.disabled=true;qty.required=false;}update();
 };
 fields.onclick=e=>{if(e.target.closest('#toggle-new-client')){const panel=$('#new-client-panel');panel.hidden=!panel.hidden;return;}if(e.target.closest('#save-inline-client')){saveInlineCustomer();return;}const button=e.target.closest('[data-selection-remove]');if(!button)return;const key=button.dataset.selectionRemove;selected.delete(key);const checkbox=fields.querySelector(`[data-batch-check="${key}"]`),qty=fields.querySelector(`[data-batch-qty="${key}"]`);if(checkbox)checkbox.checked=false;if(qty){qty.disabled=true;qty.required=false;qty.value=1;}update();};
 update();if(preparing)syncProductionPurpose();submit=d=>preparing?previewProduction([...selected.values()],{type:d.productionType,customerId:d.customerId}):readyBatch(state,[...selected.values()],catalog);$('#modal').showModal();
}

function openStockUpdate(id){
 $('#modal-title').textContent='Actualizar información';$('#form > .primary').textContent='Guardar existencias actuales';
 $('#fields').innerHTML=field('Materia prima',select('id',state.materials.map(m=>`<option value="${m.id}" ${m.id===id?'selected':''}>${esc(materialName(m))}</option>`).join('')))+'<div id="stock-fields"></div>';
 let current;
 const quarters=(name,ml,capacity)=>{const q=ml/(capacity/4),exact=Number.isInteger(q)&&q>=0&&q<=4;return select(name,`<option value="">Selecciona cuánto queda</option>${[0,1,2,3,4].map(n=>`<option value="${n}" ${exact&&q===n?'selected':''}>${n===0?'Sin existencias':`${n}/4${n===4?' · Completo':''}`}</option>`).join('')}<option value="custom" ${!exact?'selected':''}>Otra cantidad de cuartos</option>`)+`<div id="${name}-custom">${!exact?field('Cantidad de cuartos',input(name+'Custom',q,0)):''}</div>`;};
 function secondFields(){const checked=$('#has-second').checked,host=$('#second-fields');if(!checked){host.innerHTML='';return;}const m=current,b=m.secondBottle,capacity=b?.capacity??(m.kind==='Esencia'?250:m.id==='alcohol'?4000:250),factor=m.id==='alcohol'?4000:1;
 host.innerHTML=`<div class="bottle-panel"><h3>Segundo frasco</h3>${field('Capacidad del segundo frasco ('+(m.id==='alcohol'?'galones de 4 litros':'ml')+')',input('secondCapacity',capacity/factor,0.001))}<div id="second-amount"></div><p class="unit-help">La cantidad de este frasco se suma a la del primero.</p></div>`;
 const remaining=()=>{const cap=Number($('#fields [name=secondCapacity]').value)*factor;$('#second-amount').innerHTML=m.kind==='Esencia'?field('Cuánto queda en el segundo frasco',quarters('secondAmount',b?.stock??0,cap||250)):field('Cuánto queda en el segundo frasco ('+unitName(m)+')',input('secondAmount',(b?.stock??0)/unitFactor(m),0));const q=$('#second-amount [name=secondAmount]');q.required=true;if(m.kind==='Esencia')$('#second-amount').insertAdjacentHTML('beforeend',`<p class="unit-help">1/4 de este frasco = ${num(cap/4)} ml.</p>`);};remaining();$('#fields [name=secondCapacity]').onchange=remaining;
 }
 function updateFields(){current=state.materials.find(m=>m.id===$('#fields [name=id]').value);const m=current,first=bottleStock(m,1);$('#stock-fields').innerHTML=`<p>Existencias totales registradas: <strong>${num(m.stock)} ml</strong>.</p><div class="notice">Indica cuánto queda en cada frasco. Estos saldos reemplazan las existencias anteriores.</div><div class="bottle-panel"><h3>Primer frasco</h3>${m.kind==='Esencia'?field('Cuánto queda · Frasco de 250 ml',quarters('firstAmount',first,250)):field('Cuánto queda ('+unitName(m)+')',input('firstAmount',first/unitFactor(m),0))}${m.kind==='Esencia'?'<p class="unit-help">1/4 = 62.5 ml · Frasco completo = 250 ml.</p>':''}</div><label class="second-toggle"><input id="has-second" name="hasSecond" type="checkbox" ${m.secondBottle?'checked':''}> Segundo frasco</label><div id="second-fields"></div>`;$('#fields [name=firstAmount]').required=true;secondFields();$('#has-second').onchange=secondFields;}
 updateFields();$('#fields').onchange=e=>{if(e.target.name==='id')updateFields();if(['firstAmount','secondAmount'].includes(e.target.name)&&e.target.tagName==='SELECT'){const host=$('#'+e.target.name+'-custom');host.innerHTML=e.target.value==='custom'?field('Cantidad de cuartos',input(e.target.name+'Custom','',0)):'';}};
 submit=d=>{const m=current,first=Number(d.firstAmount==='custom'?d.firstAmountCustom:d.firstAmount)*unitFactor(m);let secondBottle=null;if(d.hasSecond){const capacity=Number(d.secondCapacity)*(m.id==='alcohol'?4000:1),amount=Number(d.secondAmount==='custom'?d.secondAmountCustom:d.secondAmount);secondBottle={capacity,stock:amount*(m.kind==='Esencia'?capacity/4:unitFactor(m))};}return setBottleStocks(state,{id:m.id,firstStock:first,secondBottle});};$('#modal').showModal();
}

function customerOptions(selectedId=''){
 return '<option value="">Selecciona un cliente registrado</option>'+[...(state.customers??[])].sort((a,b)=>a.name.localeCompare(b.name,'es')).map(c=>`<option value="${esc(c.id)}" ${c.id===selectedId?'selected':''}>${esc(c.name)}${c.phone?' · '+esc(c.phone):''}</option>`).join('');
}
function productionPurposeFields(){return `<div class="purpose-panel">${field('Destino de la producción',select('productionType','<option value="stock">Reposición de stock</option><option value="customer">Pedido de un cliente</option>'))}<div id="production-customer" hidden>${field('Cliente del pedido',select('customerId',customerOptions()))}<button type="button" class="secondary" id="toggle-new-client">+ Registrar nuevo cliente</button><div id="new-client-panel" class="bottle-panel" hidden><h3>Registrar nuevo cliente</h3>${field('Nombre del cliente','<input name="newClientName" maxlength="120" autocomplete="name">')}${field('Teléfono (opcional)','<input name="newClientPhone" type="tel" maxlength="50" autocomplete="tel">')}<button type="button" class="secondary" id="save-inline-client">Guardar cliente</button></div><p class="unit-help">El cliente quedará asociado a los movimientos de este lote.</p></div></div>`;}
function syncProductionPurpose(){const customer=$('#fields [name=productionType]').value==='customer';$('#production-customer').hidden=!customer;const select=$('#fields [name=customerId]');select.disabled=!customer;select.required=customer;}
async function saveInlineCustomer(){try{const next=registerCustomer(state,{name:$('#fields [name=newClientName]').value,phone:$('#fields [name=newClientPhone]').value}),id=next.customers.at(-1).id;await persist(next);$('#fields [name=customerId]').innerHTML=customerOptions(id);$('#new-client-panel').hidden=true;$('#fields [name=newClientName]').value='';$('#fields [name=newClientPhone]').value='';$('#form-error').textContent='';render();toast('Cliente registrado.');}catch(e){$('#form-error').textContent=e.message;}}
function customersView(){const list=(state.customers??[]).filter(c=>normalize(c.name+' '+c.phone).includes(normalize(search)));return title('PEDIDOS','Clientes','Registro de clientes para asociar pedidos y órdenes de producción.',action('+ Registrar nuevo cliente','customer-new'))+`<div class="toolbar"><input id="search" placeholder="Buscar por nombre o teléfono…" aria-label="Buscar cliente" value="${esc(search)}"></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Teléfono</th></tr></thead><tbody>${list.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)||'Sin teléfono'}</td></tr>`).join('')||'<tr><td colspan="2"><div class="empty">No hay clientes con esta búsqueda. Puedes registrar uno nuevo aquí o al iniciar una producción.</div></td></tr>'}</tbody></table></div>`;}
function openNewCustomer(){
 $('#modal-title').textContent='Registrar nuevo cliente';$('#form > .primary').textContent='Guardar cliente';$('#fields').innerHTML=field('Nombre del cliente','<input name="name" required maxlength="120" autocomplete="name">')+field('Teléfono (opcional)','<input name="phone" type="tel" maxlength="50" autocomplete="tel">');submit=d=>registerCustomer(state,d);$('#modal').showModal();
}

function batchNumber(batch){return 'AM-'+String(batch.number).padStart(4,'0');}
function batchDate(batch){return new Date(batch.date).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'});}
function batchPurpose(batch){return batch.purpose.type==='customer'?'Pedido · '+batch.purpose.customerName:'Producción para stock';}
function officialProductionList(batch){return `<div class="official-list"><img class="production-logo" src="./assets/logo.png" alt="Alma Mía"><div class="eyeline">ORDEN DE PRODUCCIÓN</div><h2>${batchNumber(batch)}</h2><p><strong>${esc(batchPurpose(batch))}</strong><br>${esc(batchDate(batch))}${batch.createdBy?`<br>Creado por: ${esc(batch.createdBy)}`:''}</p>${batchStatus(batch)}${batchCancellationInfo(batch)}<div class="table-wrap"><table><thead><tr><th>Perfume</th><th>Presentación</th><th>Envases</th></tr></thead><tbody>${['Dama','Caballero','Unisex'].map(g=>{const items=batch.items.filter(x=>x.category===g);return items.length?`<tr class="group-heading"><th colspan="3">${g}</th></tr>`+items.map(p=>`<tr><td>${esc(p.name)}<small>Inspirado en ${esc(p.displayReference??p.reference)} · ${esc(p.line)}</small></td><td>${p.size} ml</td><td>${p.qty}<small>${completedQuantity(p)} terminados · ${p.qty-completedQuantity(p)} ${batch.status==='cancelled'?'sin producir':'pendientes'}</small></td></tr>`).join(''):'';}).join('')}</tbody></table></div><div class="production-totals"><strong>${num(batch.totals.qty)} envases · ${num(batch.totals.volumeMl)} ml</strong><p>Materia prima para el lote:<br>${num(batch.totals.essenceMl)} ml de esencia · ${num(batch.totals.fixativeMl)} ml de galaxolide · ${num(batch.totals.alcoholMl)} ml de alcohol.</p></div></div>`;}
function previewProduction(items,purpose){
 const preview=productionPreview(state,items,catalog,purpose),dialog=$('#production-modal');
 dialog.onchange=null;dialog.innerHTML=`<div class="modal-top"><h2>Revisar antes de confirmar</h2><button type="button" id="review-close" aria-label="Cerrar vista previa">×</button></div><div class="notice">Confirmar guardará la lista en “En producción”. Las materias primas se descontarán al registrar los envases terminados en “Editar”.</div>${officialProductionList(preview)}<p id="production-error" role="alert"></p><div class="production-actions"><button type="button" class="secondary" id="review-edit">Volver a editar</button><button type="button" class="primary" id="confirm-production">Confirmar</button></div>`;
 $('#review-close').onclick=$('#review-edit').onclick=()=>dialog.close();let saving=false;
 $('#confirm-production').onclick=async()=>{if(saving||!dialog.open)return;saving=true;$('#confirm-production').disabled=true;try{const next=confirmProduction(state,preview,catalog);await persist(next);dialog.close();$('#modal').close();view='batches';search='';batchFilter='all';render();toast('Lote '+batchNumber(next.batches[0])+' confirmado y guardado.');}catch(e){$('#production-error').textContent=e.name==='QuotaExceededError'?'No hay espacio. Exporta un respaldo antes de confirmar.':e.message;}finally{saving=false;$('#confirm-production').disabled=false;}};
 dialog.showModal();return null;
}
function openLinkedSalesNote(id){$('#production-modal').close();view='sales';search='';salesPanel.showHistory();render();salesPanel.showNote(id);}
function batchSalesAction(batch){const existing=activeSalesNoteForBatch(state,batch.id);return existing?action('Ver nota de venta','batch-sale-view','secondary',`data-id="${esc(existing.id)}"`):batch.status==='cancelled'?'':action('Generar nota de venta','batch-sale','secondary',`data-id="${esc(batch.id)}"`);}
function openBatchDetails(id){const batch=(state.batches??[]).find(b=>b.id===id);if(!batch){toast('No se encontró el lote.');return;}const dialog=$('#production-modal');dialog.onchange=null;dialog.innerHTML=`<div class="modal-top"><h2>Lista del lote</h2><button type="button" id="detail-close" aria-label="Cerrar detalle del lote">×</button></div>${officialProductionList(batch)}<div class="production-actions">${batchSalesAction(batch)}${batch.status==='cancelled'?'':action(batch.purpose.type==='customer'?'Cancelar pedido':'Cancelar lote','batch-cancel','secondary sales-cancel-button',`data-id="${esc(batch.id)}"`)}<button type="button" class="secondary" id="detail-done">Cerrar</button></div>`;$('#detail-close').onclick=$('#detail-done').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();}
function batchesView(){const all=state.batches??[],list=all.filter(b=>(batchArchive==='cancelled'?b.status==='cancelled':b.status!=='cancelled')&&(batchFilter==='all'||b.purpose.type===batchFilter)&&normalize(`${batchNumber(b)} ${batchPurpose(b)} ${batchDate(b)} ${b.items.map(x=>x.name+' '+x.reference).join(' ')}`).includes(normalize(search)));return title('PRODUCCIÓN CONFIRMADA','Lotes y pedidos','Consulta las órdenes de producción, su avance, fecha y cliente asociado.',action('Iniciar producción','produce'))+`<div class="group-tabs" aria-label="Estado de producción">${[['active','Vigentes'],['cancelled','Cancelados']].map(([status,label])=>`<button type="button" data-batch-archive="${status}" aria-pressed="${batchArchive===status}">${label} (${all.filter(b=>status==='cancelled'?b.status==='cancelled':b.status!=='cancelled').length})</button>`).join('')}</div><div class="toolbar"><input id="search" aria-label="Buscar lote o pedido" placeholder="Buscar por lote, cliente, perfume o fecha…" value="${esc(search)}"><select id="batch-filter" aria-label="Destino de producción">${[['all','Todos'],['customer','Pedidos de clientes'],['stock','Producción para stock']].map(([v,t])=>`<option value="${v}" ${batchFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="notice">Selecciona “Editar” para registrar o corregir las unidades terminadas. Los insumos se descuentan únicamente al registrar avances de producción.</div><div class="table-wrap batch-history"><table><thead><tr><th>Lote</th><th>Fecha y hora</th><th>Destino</th><th>Avance</th><th>Estado</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td>${batchNumber(b)}</td><td>${esc(batchDate(b))}${b.createdBy?`<small>Creado por ${esc(b.createdBy)}</small>`:''}</td><td>${esc(batchPurpose(b))}</td><td>${batchProgress(b).completed} / ${batchProgress(b).total} terminados</td><td>${batchStatus(b)}${batchCancellationInfo(b)}</td><td><div class="batch-actions">${batchSalesAction(b)} ${b.status==='cancelled'?'':action('Editar','batch-edit','secondary',`data-id="${esc(b.id)}"`)} ${action('Ver lista','batch-detail','secondary',`data-id="${esc(b.id)}"`)} ${b.status==='cancelled'?'':action(b.purpose.type==='customer'?'Cancelar pedido':'Cancelar lote','batch-cancel','secondary sales-cancel-button',`data-id="${esc(b.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No hay lotes con esta búsqueda. Las órdenes aparecerán aquí después de su confirmación.</div></td></tr>'}</tbody></table></div>`;}

function batchCancellationInfo(batch){return batch.status==='cancelled'?`<div class="batch-cancellation-info"><strong>Motivo: ${esc(batch.cancellationReason)}</strong><small>${esc(new Date(batch.cancelledAt).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}))} · ${esc(batch.cancelledBy)}</small></div>`:'';}
function openBatchCancellation(id){
 const batch=(state.batches??[]).find(b=>b.id===id);if(!batch||batch.status==='cancelled'){toast('No se puede cancelar esta producción.');return;}const snapshot=structuredClone(batch),dialog=$('#batch-cancel-modal'),label=batch.purpose.type==='customer'?'pedido':'lote',progress=batchProgress(batch);dialog.innerHTML=`<div class="modal-top"><h2>Cancelar ${label} ${batchNumber(batch)}</h2><button type="button" id="batch-cancel-close" aria-label="Cerrar cancelación">×</button></div><p>${esc(batchPurpose(batch))}. Hay ${progress.completed} unidades terminadas y ${progress.pending} pendientes. La cancelación detiene los pendientes y conserva los avances, el stock producido y los consumos registrados.</p>${cancellationFields('batch-cancel')}<p id="batch-cancel-error" role="alert"></p><div class="production-actions"><button type="button" class="secondary" id="batch-cancel-back">Volver</button><button type="button" class="primary" id="batch-cancel-confirm">Confirmar cancelación</button></div>`;
 mountCancellationFields('batch-cancel');$('#batch-cancel-close').onclick=$('#batch-cancel-back').onclick=()=>dialog.close();let saving=false;$('#batch-cancel-confirm').onclick=async()=>{if(saving)return;saving=true;$('#batch-cancel-confirm').disabled=true;try{const actor=cloud?.enabled?cloud.member?.display_name:sessionUser,next=cancelBatch(state,{batchId:id,...readCancellationFields('batch-cancel'),actor,expectedBatch:snapshot});await persist(next);dialog.close();$('#production-modal').close();view='batches';batchArchive='cancelled';render();toast('Cancelación registrada con su motivo.');}catch(e){$('#batch-cancel-error').textContent=e.message;$('#batch-cancel-confirm').disabled=false;}finally{saving=false;}};dialog.showModal();
}
function batchStatus(batch){const p=batchProgress(batch);return `<span class="production-status ${p.cancelled?'is-cancelled':p.ready?'is-ready':'is-progress'}"><span aria-hidden="true"></span>${p.label}</span>`;}
function openBatchEditor(id,filter='all',message=''){
 const batch=(state.batches??[]).find(b=>b.id===id);if(!batch){toast('No se encontró el lote.');return;}if(batch.status==='cancelled'){openBatchDetails(id);return;}const dialog=$('#production-modal'),progress=batchProgress(batch);
 const items=batch.items.filter(i=>filter==='all'||(filter==='pending'?completedQuantity(i)<i.qty:completedQuantity(i)===i.qty));
 dialog.onchange=null;dialog.innerHTML=`<div class="modal-top"><h2>Editar ${batchNumber(batch)}</h2><button type="button" id="batch-editor-close" aria-label="Cerrar edición del lote">×</button></div><p>${esc(batchPurpose(batch))}<br>Creado: ${esc(batchDate(batch))}${batch.createdBy?`<br>Creado por: ${esc(batch.createdBy)}`:''}</p>${batchStatus(batch)}<div class="production-totals"><strong>${progress.completed} terminados · ${progress.pending} pendientes · ${progress.total} en total</strong><progress class="batch-progress" max="${progress.total}" value="${progress.completed}" aria-label="Avance de producción"></progress>${batch.completedAt?`<p>Completado: ${esc(new Date(batch.completedAt).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}))}</p>`:''}</div><p>Puedes aumentar o corregir los envases terminados. Al reducir una cantidad se retiran stock de perfumes y se restituyen sus insumos; el lote vuelve a En producción si quedan pendientes.</p><div class="group-tabs">${[['all','Todos'],['pending','Pendientes'],['done','Terminados']].map(([v,t])=>`<button type="button" data-progress-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div><p id="batch-editor-message" role="status">${esc(message)}</p><div class="batch-edit-list">${items.map(i=>{const done=completedQuantity(i),pending=i.qty-done;return `<article class="batch-edit-row"><div><strong>${esc(i.name)}</strong><small>Inspirado en ${esc(i.reference)} · ${i.size} ml · ${i.category}</small><span class="badge ${pending?'':'green'}">${done} terminados · ${pending} pendientes</span></div><div class="batch-edit-controls"><label class="field">Unidades terminadas de ${i.qty}<input type="number" min="0" max="${i.qty}" step="1" value="${done}" data-progress-qty="${i.id}-${i.size}" aria-label="Envases terminados de ${esc(i.name)} de ${i.size} ml" ></label><label class="batch-complete"><input type="checkbox" data-progress-complete="${i.id}-${i.size}" ${pending?'':'checked'}> ${pending?'Completar pendientes':'Terminado'}</label></div></article>`}).join('')||'<div class="empty">No hay perfumes en esta vista.</div>'}</div><div class="production-actions">${batchSalesAction(batch)}${action(batch.purpose.type==='customer'?'Cancelar pedido':'Cancelar lote','batch-cancel','secondary sales-cancel-button',`data-id="${esc(batch.id)}"`)}<button type="button" class="secondary" id="batch-editor-done">Cerrar</button></div>`;
 $('#batch-editor-close').onclick=$('#batch-editor-done').onclick=()=>dialog.close();dialog.querySelectorAll('[data-progress-filter]').forEach(button=>button.onclick=()=>openBatchEditor(id,button.dataset.progressFilter));
 dialog.onchange=async e=>{const key=e.target.dataset.progressQty||e.target.dataset.progressComplete;if(!key)return;const[productId,size]=key.split('-'),item=batch.items.find(i=>i.id===productId&&i.size===Number(size)),completed=e.target.dataset.progressComplete?(e.target.checked?item.qty:0):Number(e.target.value);try{if(e.target.value===''&&!e.target.dataset.progressComplete)throw Error('Indica cuántos envases has terminado.');const next=completeBatchItem(state,{batchId:id,id:productId,size:Number(size),completed},catalog);await persist(next);render();openBatchEditor(id,filter,'Cantidad corregida y guardada. Materias primas y stock de perfumes actualizados.');}catch(err){openBatchEditor(id,filter,err.message);}};
 if(!dialog.open)dialog.showModal();
}

function canRefreshCloudView(){return view!=='scanner'&&!document.querySelector('dialog[open]')&&!document.activeElement?.matches('input,textarea,select');}
function refreshCloudView(){if(remoteRenderPending&&canRefreshCloudView()){remoteRenderPending=false;render();}}
function cacheCloudState(data){try{clearBusinessCache(localStorage);}catch{}}
function updateCloudStatus(){if(!cloud)return;const wasLocked=document.body.classList.contains('access-locked');if(cloud.mode==='auth'&&!cloud.user&&!wasLocked){clearBusinessCache(localStorage);state=initialState(catalog);sessionUser='';sessionStorage.removeItem('alma-mia-session-user');}updateAccessScreen();if(wasLocked&&hasAppAccess(cloud))render();const button=$('#cloud-status');button.textContent=cloud.enabled?cloud.message:'Conectar dispositivos';$('#storage-label').textContent=cloud.enabled?(cloud.mode==='ready'&&cloud.connected?'Datos compartidos en la nube':'Nube pendiente de conexión'):'Guardado en este navegador';$('#session-user').disabled=cloud.enabled;if(cloud.member){sessionUser=cloud.member.display_name;$('#session-user').value=sessionUser;}if(view==='cloud'&&canRefreshCloudView())render();}
function preserveLocalInventory(){const backupKey='alma-mia-before-cloud-'+new Date().toISOString();localStorage.setItem(backupKey,JSON.stringify(state));localStorage.setItem('alma-mia-before-cloud-latest',backupKey);}
function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function cloudView(){
 const config=cloud?.config,localSummary=`${state.materials.filter(m=>m.stock>0).length} materias con existencias · ${Object.values(state.ready).reduce((a,b)=>a+b,0)} stock de perfumes · ${state.movements.length} movimientos`;
 let content='';
 if(config){if(cloud.mode==='auth'||cloud.mode==='error'){content=`<div class="card"><h2>Iniciar sesión</h2><p>Cada persona usa su correo y contraseña de Supabase. Luis o Ximena se asigna según la cuenta autorizada.</p><form id="cloud-login">${field('Correo','<input type="email" name="email" required autocomplete="username">')}${field('Contraseña','<input type="password" name="password" required autocomplete="current-password">')}<button class="primary" type="submit">Iniciar sesión</button></form></div>`;}else if(cloud.mode==='choice'){content=`<div class="card"><h2>Ya existe el inventario compartido</h2><p>Se conservó una copia de lo que había en este navegador. Abre la nube para ver el mismo inventario que los demás dispositivos.</p><button class="primary" id="cloud-accept">Abrir inventario compartido</button></div>`;}else if(cloud.mode==='empty'){content=`<div class="card"><h2>Subir el inventario por primera vez</h2><p>Haz este paso desde la computadora que tiene la información completa. No subas un inventario vacío desde el celular.</p><div class="notice">Este dispositivo: ${localSummary}</div><button class="primary" id="cloud-upload">Subir este inventario a la nube</button></div>`;}else if(cloud.mode==='ready'){content=`<div class="card"><h2>Inventario compartido conectado</h2><p>Sesión de <strong>${esc(cloud.member?.display_name)}</strong>. Los cambios se guardan en la nube y llegan a los demás dispositivos conectados. Si otra sesión guarda antes, se evita sobrescribirla y se pide repetir la acción sobre los datos recientes.</p><button class="secondary" id="cloud-refresh">Actualizar ahora</button></div>`;}else content='<div class="card"><p>Conectando con Supabase…</p></div>';}
 return title('COMPUTADORA Y CELULAR','Conexión y sincronización','Comparte el mismo inventario, clientes y pedidos en tus dispositivos.')+`<div class="notice" role="status">${esc(cloud?.message??'Solo en este navegador. Todavía no hay sincronización.')}</div>${cloudUiError?`<p role="alert" class="dictation-warning">${esc(cloudUiError)}</p>`:''}<div class="cloud-layout">${content}<div class="card"><${config?'details':'section'}><${config?'summary':'h2'}>${config?'Revisar configuración de Supabase':'Configurar el proyecto gratuito'}</${config?'summary':'h2'}><p>Primero crea el proyecto y ejecuta los archivos SQL de configuración y miembros. <a href="https://github.com/maccmotorservice-rgb/Alma-M-a-app/blob/main/supabase/LEEME.md" target="_blank" rel="noopener">Ver instrucciones</a>.</p><form id="cloud-config">${field('Project URL',`<input name="url" type="url" required placeholder="https://tu-proyecto.supabase.co" value="${esc(config?.url??'')}">`)}${field('Clave publicable o anon',`<input name="key" required type="password" autocomplete="off" placeholder="sb_publishable_…" value="${esc(config?.key??'')}">`)}<p class="unit-help">Solo configuración pública. Nunca pegues service_role, una clave secreta ni la contraseña de la base de datos.</p><button class="primary" type="submit">${config?'Guardar configuración':'Conectar Supabase'}</button></form></${config?'details':'section'}></div><div class="card"><h2>Respaldo y sesión</h2><p>Al conectar por primera vez, la copia local se conserva antes de cargar datos de la nube. El respaldo incluye clientes y movimientos.</p><button class="secondary" id="cloud-backup">Descargar copia local anterior</button>${cloud.failedSave?'<button class="secondary" id="cloud-failed">Descargar cambio que no se confirmó</button>':''}${cloud.user?'<button class="secondary" id="cloud-logout">Cerrar sesión en este dispositivo</button>':''}</div></div>`;
}
function mountCloud(){
 $('#cloud-config').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{cloudUiError='';preserveLocalInventory();await cloud.configure(data);render();}catch(err){cloudUiError=err.message;render();}};
 const login=$('#cloud-login');if(login)login.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));e.target.elements.password.value='';try{cloudUiError='';await cloud.signIn(data.email,data.password);render();}catch(err){cloudUiError=err.message;render();}};
 if($('#cloud-accept'))$('#cloud-accept').onclick=async()=>{try{cloudUiError='';await cloud.acceptRemote();render();}catch(e){cloudUiError=e.message;render();}};
 if($('#cloud-upload'))$('#cloud-upload').onclick=async()=>{if(!confirm('El inventario de ESTE dispositivo será la primera copia compartida. ¿Es el inventario completo que quieres usar?'))return;try{cloudUiError='';preserveLocalInventory();await cloud.initialize(state);render();}catch(e){cloudUiError=e.message;render();}};
 if($('#cloud-refresh'))$('#cloud-refresh').onclick=()=>cloud.pull();
 if($('#cloud-logout'))$('#cloud-logout').onclick=async()=>{await cloud.signOut();clearBusinessCache(localStorage);state=initialState(catalog);sessionUser='';sessionStorage.removeItem('alma-mia-session-user');view='overview';render();};
 if($('#cloud-failed'))$('#cloud-failed').onclick=()=>downloadJson(cloud.failedSave,'alma-mia-cambio-no-confirmado.json');
 $('#cloud-backup').onclick=()=>{try{const backupKey=localStorage.getItem('alma-mia-before-cloud-latest'),raw=backupKey&&localStorage.getItem(backupKey);if(!raw)throw Error('Todavía no hay copia local anterior. Usa Exportar respaldo para descargar la actual.');downloadJson(JSON.parse(raw),'alma-mia-antes-de-conectar.json');}catch(e){toast(e.message);}};
}
